<?php require 'config/bootstrap.php'; require_login(); $q=trim($_GET['q']??''); $st=$_GET['status']??''; $pg=max(1,(int)($_GET['p']??1)); $per=15;
$w='user_id=?'; $a=[uid()]; if($q!==''){$w.=' AND (title LIKE ? OR parties LIKE ?)';$a[]="%$q%";$a[]="%$q%";} if(in_array($st,['draft','under_review','active','expired','archived'],true)){$w.=' AND status=?';$a[]=$st;}
$cnt=db()->prepare("SELECT COUNT(*) FROM contracts WHERE $w");$cnt->execute($a);$tot=(int)$cnt->fetchColumn();
$s=db()->prepare("SELECT * FROM contracts WHERE $w ORDER BY created_at DESC LIMIT $per OFFSET ".(($pg-1)*$per));$s->execute($a);$rows=$s->fetchAll();
page_head('Contracts'); ?><div class="d-flex justify-content-between mb-3"><h1 class="h3">Contracts</h1><div><a class="btn btn-outline-light" href="export.php?t=contracts">CSV</a> <a class="btn btn-primary" href="contract_new.php">New contract</a></div></div>
<form class="row g-2 mb-3"><div class="col-md-5"><input class="form-control" name="q" placeholder="Search title or parties" value="<?=e($q)?>"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['draft','under_review','active','expired','archived'] as $x):?><option <?=$st===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-outline-light">Filter</button></div></form>
<div class="cardx table-responsive"><?php if(!$rows):?><div class="empty">No contracts found.</div><?php else:?><table class="table"><thead><tr><th>Title</th><th>Type</th><th>Status</th><th>Expiry</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="contract.php?id=<?=$r['id']?>"><?=e($r['title'])?></a></td><td><?=e($r['contract_type'])?></td><td><?=e($r['status'])?></td><td><?=e($r['expiry_date']?:'—')?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div>
<?php if($tot>$per):?><div class="mt-3"><?php for($i=1;$i<=ceil($tot/$per);$i++):?><a class="btn btn-sm <?=$i==$pg?'btn-primary':'btn-outline-light'?>" href="?<?=e(http_build_query(['q'=>$q,'status'=>$st,'p'=>$i]))?>"><?=$i?></a> <?php endfor;?></div><?php endif; page_foot();
